TRUNCATE "hotel_property" RESTART IDENTITY CASCADE;
INSERT INTO "hotel_property" ("id", "name", "slug", "tagline", "vibe_tags", "description", "city", "country", "address", "phone", "email", "stars", "currency", "service_rate", "tax_rate", "check_in_hour", "check_out_hour", "image_url", "latitude", "longitude", "is_active", "created_at") VALUES (33, 'Aurelia Angkor Sanctuary', 'aurelia-angkor-sanctuary', 'Temple-gate sanctuary amid frangipani gardens, minutes from Angkor Wat.', 'Temples, History, Culture', 'Minutes from the gates of Angkor — the largest religious monument on earth — the sanctuary sits in frangipani gardens on the temple circuit road. Siem Reap, Cambodia''s most-loved destination for temples, history and culture with 688 places to stay, is at its calmest here: sunrise departures for Angkor Wat, an afternoon by the pool, Kampot-pepper tasting menus in the evening, Pub Street and the Old Market a short tuk-tuk ride away.', 'Siem Reap', 'Cambodia', '1 Aurelia Way, Siem Reap', '+855 23 900 384', 'stay@aurelia-angkor-sanctuary.example', 5, 'USD', 0.050, 0.100, 14, 12, '/static/img/props/siem-reap.jpg', 13.352, 103.857, TRUE, '2026-09-21 07:54:43');
INSERT INTO "hotel_property" ("id", "name", "slug", "tagline", "vibe_tags", "description", "city", "country", "address", "phone", "email", "stars", "currency", "service_rate", "tax_rate", "check_in_hour", "check_out_hour", "image_url", "latitude", "longitude", "is_active", "created_at") VALUES (37, 'Aurelia Battambang Riverside', 'aurelia-battambang-riverside', 'Colonial-era riverside maison in Cambodia''s artistic second city.', 'Countryside, Friendly Locals, Sightseeing', 'Cambodia''s artistic second city is rated for countryside, friendly locals and sightseeing — colonial shophouses, art studios and the slow bend of the Sangker River. The riverside maison is a restored French-era townhouse on the riverfront boulevard: the bamboo train, hilltop Wat Banan and an evening at the Phare circus are all short rides away; house bicycles and the river terrace handle the rest.', 'Battambang', 'Cambodia', '1 Aurelia Way, Battambang', '+855 23 900 510', 'stay@aurelia-battambang-riverside.example', 4, 'USD', 0.050, 0.100, 14, 12, '/static/img/props/battambang.jpg', 13.098, 103.205, TRUE, '2026-09-21 07:54:43');
INSERT INTO "hotel_property" ("id", "name", "slug", "tagline", "vibe_tags", "description", "city", "country", "address", "phone", "email", "stars", "currency", "service_rate", "tax_rate", "check_in_hour", "check_out_hour", "image_url", "latitude", "longitude", "is_active", "created_at") VALUES (32, 'Aurelia Grand Phnom Penh', 'aurelia-grand-phnom-penh', 'Riverside grand hotel on the Tonlé Sap — the flagship of the collection.', 'History, Culture, Markets', 'On the Tonlé Sap riverfront promenade, the flagship puts the Royal Palace, the National Museum and the night market inside a ten-minute stroll. Phnom Penh is rated by travellers for history, culture and markets — and the house answers with a rooftop Mekong terrace, Khmer-fusion dining and a spa above the river. Palace ferries and Sisowath Quay cafés leave from the door; Phnom Penh International is 40 minutes away.', 'Phnom Penh', 'Cambodia', '1 Aurelia Way, Phnom Penh', '+855 23 900 754', 'stay@aurelia-grand-phnom-penh.example', 5, 'USD', 0.050, 0.100, 14, 12, '/static/img/props/phnom-penh.jpg', 11.5656, 104.9325, TRUE, '2026-09-21 07:54:43');
INSERT INTO "hotel_property" ("id", "name", "slug", "tagline", "vibe_tags", "description", "city", "country", "address", "phone", "email", "stars", "currency", "service_rate", "tax_rate", "check_in_hour", "check_out_hour", "image_url", "latitude", "longitude", "is_active", "created_at") VALUES (34, 'Aurelia Kep Cove Resort', 'aurelia-kep-cove', 'Barefoot cove resort facing Kampot pepper hills and crab-market sunsets.', 'Seafood, Tranquillity, Relaxation', 'Kep is Cambodia''s quiet coast — a seaside town rated for seafood, tranquillity and relaxation, famous for its crab market and pepper farms. The cove resort faces the water below Kep National Park''s jungle hills: barefoot lawns, a saltwater pool, bicycles for the coast road to Kep Beach and the ferry jetty to Koh Tonsay (Rabbit Island). Sunset at the crab market is five minutes away.', 'Kep', 'Cambodia', '1 Aurelia Way, Kep', '+855 23 900 227', 'stay@aurelia-kep-cove.example', 4, 'USD', 0.050, 0.100, 14, 12, '/static/img/props/kep.webp', 10.54, 104.315, TRUE, '2026-09-21 07:54:43');
INSERT INTO "hotel_property" ("id", "name", "slug", "tagline", "vibe_tags", "description", "city", "country", "address", "phone", "email", "stars", "currency", "service_rate", "tax_rate", "check_in_hour", "check_out_hour", "image_url", "latitude", "longitude", "is_active", "created_at") VALUES (35, 'Aurelia Koh Rong Overwater', 'aurelia-koh-rong-overwater', 'Overwater villas on a private white-sand spit in the Gulf of Thailand.', 'Sandy Beaches, Relaxation, Beaches', 'A boat ride from the Sihanoukville pier, Koh Rong is rated by travellers for sandy beaches, relaxation and beaches — powder-white sand and warm, glass-clear gulf water. The resort spans a private spit: overwater villas above a shallow house reef, beach bungalows under the casuarinas, kayaks and snorkel gear at the jetty, bioluminescent plankton on night swims. No roads, no cars — only the tide table.', 'Koh Rong', 'Cambodia', '1 Aurelia Way, Koh Rong', '+855 23 900 489', 'stay@aurelia-koh-rong-overwater.example', 5, 'USD', 0.050, 0.100, 14, 12, '/static/img/props/koh-rong.jpg', 10.67, 103.25, TRUE, '2026-09-21 07:54:43');
INSERT INTO "hotel_property" ("id", "name", "slug", "tagline", "vibe_tags", "description", "city", "country", "address", "phone", "email", "stars", "currency", "service_rate", "tax_rate", "check_in_hour", "check_out_hour", "image_url", "latitude", "longitude", "is_active", "created_at") VALUES (36, 'Aurelia Sihanoukville Marina Bay', 'aurelia-marina-bay', 'Marina-front towers with yacht-club access and rooftop sea pools.', 'Beaches, Sandy Beaches, Relaxation', 'Cambodia''s beach capital — rated for beaches, sandy beaches and relaxation — arcs around a peninsula of bays from Ochheuteal to Sokha and Otres. Marina Bay rises over the yacht harbour with rooftop sea pools and a marina club, shuttle boats to the island reefs, Kbal Chhay waterfall and Ream National Park inland, and the Koh Rong ferries leaving from the pier below the hotel.', 'Sihanoukville', 'Cambodia', '1 Aurelia Way, Sihanoukville', '+855 23 900 846', 'stay@aurelia-marina-bay.example', 4, 'USD', 0.050, 0.100, 14, 12, '/static/img/props/sihanoukville.webp', 10.57, 103.81, TRUE, '2026-09-21 07:54:43');
INSERT INTO "hotel_property" ("id", "name", "slug", "tagline", "vibe_tags", "description", "city", "country", "address", "phone", "email", "stars", "currency", "service_rate", "tax_rate", "check_in_hour", "check_out_hour", "image_url", "latitude", "longitude", "is_active", "created_at") VALUES (38, 'Raffles Hotel Le Royal, Phnom Penh', 'raffles-hotel-le-royal', 'The 1929 colonial grande dame — Cambodia''s most awarded address.', 'Heritage, History, Culture', 'Opened in 1929 as the Hotel Royal and restored for its century, Le Royal is Phnom Penh''s grande dame: white colonnades, frangipani lawns and the vaulted Elephant Bar where Chaplin and Jackie Kennedy once drank. Named Cambodia''s top city hotel by Travel + Leisure (2026), a MICHELIN Key holder and No. 2 in Southeast Asia in the Condé Nast Readers'' Choice Awards, it pairs heritage suites with twin pools, a spa and French-Khmer fine dining — five minutes from the Royal Palace.', 'Phnom Penh', 'Cambodia', '1 Aurelia Way, Phnom Penh', '+855 23 900 862', 'stay@raffles-hotel-le-royal.example', 5, 'USD', 0.050, 0.100, 14, 12, '/static/img/props/le-royal.jpg', 11.5699, 104.929, TRUE, '2026-09-21 07:54:43');
INSERT INTO "hotel_property" ("id", "name", "slug", "tagline", "vibe_tags", "description", "city", "country", "address", "phone", "email", "stars", "currency", "service_rate", "tax_rate", "check_in_hour", "check_out_hour", "image_url", "latitude", "longitude", "is_active", "created_at") VALUES (39, 'Rosewood Phnom Penh', 'rosewood-phnom-penh', 'Sky-high ultra-luxury crowning the Vattanac Capital Tower — the capital''s glass landmark.', 'Skyline, Heritage, Luxury', 'Floors 30 to 42 of the Vattanac Capital Tower on Monivong Boulevard — Cambodia''s tallest building — hold the Rosewood''s glass-walled rooms above the rooftops. The residence-style interiors layer Khmer silk, lacquer and art-deco references over skyline views from the Mekong to the palace spires; the rooftop bar and the sky lobby''s lantern light are city institutions. Wat Phnom, the rail-market food stalls and the riverfront are minutes below.', 'Phnom Penh', 'Cambodia', '1 Aurelia Way, Phnom Penh', '+855 23 900 887', 'stay@rosewood-phnom-penh.example', 5, 'USD', 0.050, 0.100, 14, 12, '/static/img/props/rosewood.jpg', 11.5687, 104.9309, TRUE, '2026-09-21 07:54:43');
INSERT INTO "hotel_property" ("id", "name", "slug", "tagline", "vibe_tags", "description", "city", "country", "address", "phone", "email", "stars", "currency", "service_rate", "tax_rate", "check_in_hour", "check_out_hour", "image_url", "latitude", "longitude", "is_active", "created_at") VALUES (40, 'Sala Lodges', 'sala-lodges', 'Eleven rescued Khmer heritage houses reassembled amid rice paddies and palms.', 'Heritage, Gardens, Quiet', 'Eleven authentic Khmer heritage houses — some fifty years old, dismantled in villages across the countryside and reassembled beam by beam — stand in a garden of rice paddies, sugar palms and banana trees on Salakomreuk Road. Each lodge keeps its own character: hand-made quilts, rusted-wood walls, deep verandas. A twenty-metre sunset pool and a modern pavilion restaurant anchor the estate; Angkor''s temple road is a short tuk-tuk ride away, Pub Street and the Old Market closer still.', 'Siem Reap', 'Cambodia', '1 Aurelia Way, Siem Reap', '+855 23 900 256', 'stay@sala-lodges.example', 5, 'USD', 0.050, 0.100, 14, 12, '/static/img/props/sala-lodges.jpg', 13.3454, 103.8605, TRUE, '2026-09-21 07:54:43');
INSERT INTO "hotel_property" ("id", "name", "slug", "tagline", "vibe_tags", "description", "city", "country", "address", "phone", "email", "stars", "currency", "service_rate", "tax_rate", "check_in_hour", "check_out_hour", "image_url", "latitude", "longitude", "is_active", "created_at") VALUES (41, 'Song Saa Private Island', 'song-saa-private-island', 'Cambodia''s first private-island reserve — twin islets, one house reef, barefoot villas.', 'Island, Eco-Luxury, Romance', 'Two islets — Koh Ouen and Koh Bong — joined by a footbridge over a self-declared marine reserve in the Koh Rong archipelago: Cambodia''s first private-island resort and its most serious conservation story. Villas of driftwood, thatch and stone step straight onto the house reef; overwater reserves hang above turquoise shallows where black-tip sharks patrol. Forty-five minutes by speedboat from Sihanoukville, the island runs on solar power, reef restoration and barefoot silence.', 'Koh Rong', 'Cambodia', '1 Aurelia Way, Koh Rong', '+855 23 900 999', 'stay@song-saa-private-island.example', 5, 'USD', 0.050, 0.100, 14, 12, '/static/img/props/song-saa.jpg', 10.7555, 103.2621, TRUE, '2026-09-21 07:54:43');
SELECT setval(pg_get_serial_sequence('hotel_property', 'id'), COALESCE(MAX("id"), 1)) FROM "hotel_property";

