TRUNCATE "hotel_attraction" RESTART IDENTITY CASCADE;
INSERT INTO "hotel_attraction" ("id", "property_id", "name", "blurb", "icon", "distance", "sort", "latitude", "longitude") VALUES (100, 33, 'Angkor Wat at sunrise', 'The largest religious monument on earth, mirrored in its moat.', 'ri-ancient-gate-line', '6 km', 0, 13.4125, 103.867);
INSERT INTO "hotel_attraction" ("id", "property_id", "name", "blurb", "icon", "distance", "sort", "latitude", "longitude") VALUES (133, 40, 'Angkor Wat at sunrise', 'The largest religious monument on earth, mirrored in its moat.', 'ri-ancient-gate-line', '7 km', 0, 13.4125, 103.867);
INSERT INTO "hotel_attraction" ("id", "property_id", "name", "blurb", "icon", "distance", "sort", "latitude", "longitude") VALUES (105, 34, 'Kep crab market', 'Blue-swimmer crab stalls beneath the famous statue — eat at sunset.', 'ri-restaurant-line', '1.5 km', 0, 10.5364, 104.3098);
INSERT INTO "hotel_attraction" ("id", "property_id", "name", "blurb", "icon", "distance", "sort", "latitude", "longitude") VALUES (137, 41, 'Koh Ouen house-reef dive', 'Step off the jetty into a restored reef of coral gardens and seahorses.', 'ri-water-flash-line', '0.2 km', 0, 10.756, 103.261);
INSERT INTO "hotel_attraction" ("id", "property_id", "name", "blurb", "icon", "distance", "sort", "latitude", "longitude") VALUES (94, 32, 'Mekong & Tonlé Sap sunset cruise', 'Boats leave steps from the door; gold light where four rivers meet.', 'ri-sailboat-line', 'from the pier', 0, 11.5656, 104.9325);
INSERT INTO "hotel_attraction" ("id", "property_id", "name", "blurb", "icon", "distance", "sort", "latitude", "longitude") VALUES (113, 36, 'Ochheuteal & Otres beaches', 'Beach clubs and long sand at Ochheuteal; quieter palms at Otres.', 'ri-umbrella-line', '3 km', 0, 10.5653, 103.8186);
INSERT INTO "hotel_attraction" ("id", "property_id", "name", "blurb", "icon", "distance", "sort", "latitude", "longitude") VALUES (129, 39, 'Royal Palace & Silver Pagoda', 'Gilded spires and the Emerald Buddha from the tower''s south glass.', 'ri-government-line', '1.3 km', 0, 11.5625, 104.9312);
INSERT INTO "hotel_attraction" ("id", "property_id", "name", "blurb", "icon", "distance", "sort", "latitude", "longitude") VALUES (109, 35, 'Saracen Bay', 'A crescent of powder-white sand — the island''s postcard view.', 'ri-umbrella-line', '1 km', 0, 10.6647, 103.2352);
INSERT INTO "hotel_attraction" ("id", "property_id", "name", "blurb", "icon", "distance", "sort", "latitude", "longitude") VALUES (123, 38, 'The Elephant Bar', 'A vaulted 1929 bar of murals and memoirs — order the Femme Fatale.', 'ri-goblet-line', 'in-house', 0, 11.5699, 104.929);
INSERT INTO "hotel_attraction" ("id", "property_id", "name", "blurb", "icon", "distance", "sort", "latitude", "longitude") VALUES (118, 37, 'The bamboo train (norry)', 'The famous flatbed rail ride out through the rice fields.', 'ri-train-line', '4 km', 0, 13.0736, 103.2226);
INSERT INTO "hotel_attraction" ("id", "property_id", "name", "blurb", "icon", "distance", "sort", "latitude", "longitude") VALUES (114, 36, 'Bokor National Park', 'Cloud-forest hills and the ruins of a colonial hill station.', 'ri-landscape-line', '45 km', 1, 10.6631, 104.0569);
INSERT INTO "hotel_attraction" ("id", "property_id", "name", "blurb", "icon", "distance", "sort", "latitude", "longitude") VALUES (110, 35, 'House-reef snorkelling', 'Coral gardens and clownfish at slack tide, no boat needed.', 'ri-water-flash-line', 'off the jetty', 1, 10.66, 103.24);
